async function sidecarArgv($, sid, run) {
  const configDir = await $.env.get("CLAUDE_CONFIG_DIR");
  const hyouiSessionId = await $.env.get("HYOUI_SESSION_ID");
  return [
    `${$.plugin.root}/bin/ccmsg`,
    "sidecar",
    "--sid",
    sid,
    "--run",
    run.id,
    "--started-at",
    String(run.startedAt),
