  state.interactive ??= (await $.session.surfaces()).length > 0;
  if (!state.interactive)
    return;
  const sid = await $.session.id();
  if (state.sid !== undefined && state.sid !== sid)
    nextGeneration(state);
  state.sid = sid;
  if (state.sidecar?.sid === sid)
    return;
