    after: async () => {
      await unguide($);
    }
  })).catch(async (_$, e, next) => next(e));
  on("session.measure", async ($, e, next) => observe($, e, next, "session.measure", SessionMeasureInputSchema, {
    after: async (input) => {
      const window = input.context?.window;
      if (window === undefined)
        return;
      const at = Math.floor(await $.clock.now());
      const tokens = input.context?.tokens;
      state.facts = {
        ...state.facts,
        context: contextFacts({ window, ...tokens !== undefined ? { tokens } : {} }, at)
