  PEERS_TIMEOUT_MS,
  REPLY_TIMEOUT_MS,
  RESPAWN_MAX_MS,
  RESPAWN_MIN_MS,
  SAY_TIMEOUT_MS,
  SEND_TIMEOUT_MS,
  STABLE_MS,
  agentMessage,
  answer,
  beginArgv,
  factsArgv,
  handlePromptSend,
  hyouiEnterArgv,
  lineSplitter,
  newState,
  peerArgv,
  register,
  replyArgv,
  samePrompt
